def get_db():
    db = SessionLocal()
    try:
        yield db
        db.commit()
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()

@app.post("/payments")
def pay(
    body: Payment, db: Session = Depends(get_db)
) -> dict:
    db.add(PaymentRow(**body.model_dump()))
    return {"status": "recorded"}

